// Columnas esperadas en la planilla:
// nombre | telefono | legajo (opcional) | company_id
// Filtra filas sin telefono y normaliza los datos

const contacts = [];

for (const item of $input.all()) {
  const row = item.json;
  const telefono = String(row.telefono || row.Telefono || row.TELEFONO || '').trim();
  if (!telefono) continue;

  contacts.push({
    nombre: String(row.nombre || row.Nombre || row.NOMBRE || 'Sin nombre').trim(),
    telefono: telefono,
    legajo: String(row.legajo || row.Legajo || row.LEGAJO || '').trim() || null,
    company_id: String(row.company_id || row.empresa || row.Empresa || '').trim() || null
  });
}

// Agrupar por empresa (company_id)
const byCompany = {};
for (const c of contacts) {
  const cid = c.company_id || 'default';
  if (!byCompany[cid]) byCompany[cid] = [];
  byCompany[cid].push({ nombre: c.nombre, telefono: c.telefono, legajo: c.legajo });
}

// Devolver un item por empresa
return Object.entries(byCompany).map(([company_id, contacts]) => ({
  json: { company_id, contacts }
}));
